:root{color-scheme:light;--bg:#fff;--panel:#f7f8fa;--ink:#20242d;--muted:#707781;--border:#dfe3ea;--accent:#2563eb;--soft:#eff6ff;--soft-border:#bdd7ff;--shadow:0 8px 32px #11182710;--danger:#b42318}
:root.dark{color-scheme:dark;--bg:#1e1d30;--panel:#29283e;--ink:#f0eff8;--muted:#b0aec5;--border:#48465f;--accent:#b397ff;--soft:#292641;--soft-border:#615082;--shadow:0 8px 32px #0003;--danger:#ffb4ab}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,textarea,select{font:inherit}button,a,input,select,textarea{-webkit-tap-highlight-color:transparent}button{cursor:pointer;color:inherit}button{border:1px solid transparent;background:transparent;border-radius:9px;padding:8px 12px;font-weight:550}button:hover{background:var(--panel)}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--accent);outline-offset:3px}a{color:var(--accent)}button.primary{background:var(--accent);color:white;border-color:var(--accent)}.dark button.primary{color:#171221}button.outline{border-color:var(--border);background:var(--bg)}button.outline:hover{border-color:var(--accent)}.text-button{color:var(--accent);padding:0;font-size:12px;white-space:nowrap}.icon-button{font-size:24px;line-height:1;padding:5px;min-width:34px;min-height:34px}.quiet{font-size:13px;padding:6px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}[hidden]{display:none!important}h1,h2,p{margin:0}h2{font-size:19px;line-height:1.3}input,select,textarea{border:1px solid var(--border);background:var(--bg);color:var(--ink);border-radius:9px;padding:10px;min-width:0}textarea{resize:none}#studio{height:100dvh;display:flex;flex-direction:column;min-width:0}.topbar{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:13px 16px;border-bottom:1px solid var(--border);flex:none}.brand{display:flex;align-items:center;gap:6px;font-size:17px;font-weight:700;color:var(--accent);white-space:nowrap;letter-spacing:-.4px}.brand-mark{width:34px;height:26px;object-fit:contain;flex:none}.brand-ai{font-weight:500}.topbar nav{display:flex;align-items:center;gap:2px}#conversation{flex:1;min-height:0;overflow:auto;scrollbar-gutter:stable;padding:28px 20px 20px;scroll-behavior:smooth}.chat-width{width:100%;max-width:800px;margin:0 auto}.welcome{min-height:260px;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;padding:24px 0;gap:16px}.welcome h1{font-size:28px;line-height:1.2;letter-spacing:-.7px;font-weight:650}.welcome p{color:var(--muted);max-width:490px}.suggestions{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}.suggestions button{background:var(--panel);border-color:var(--border);font-size:13px}.turn{display:flex;flex-direction:column;gap:14px;margin-bottom:28px}.user-message{align-self:flex-end;background:var(--panel);border-radius:20px 20px 5px 20px;padding:12px 18px;max-width:90%;white-space:pre-wrap;overflow-wrap:anywhere}.assistant-note{color:var(--muted);padding:0 2px}.result{border:1px solid var(--soft-border);background:var(--soft);border-radius:18px;padding:12px;overflow:hidden}.result-image{display:block;width:100%;max-height:500px;object-fit:contain;background:repeating-conic-gradient(#aaa2 0% 25%,transparent 0% 50%) 50%/18px 18px;border-radius:10px}.result-description{font-size:13px;color:var(--muted);padding:12px 2px 4px}.result-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.result-actions button,.result-actions a{font-size:13px;border:1px solid var(--soft-border);border-radius:18px;padding:7px 12px;background:var(--bg);text-decoration:none;color:var(--accent);font-weight:550}.result-actions button:hover{border-color:var(--accent)}.result-actions button.applied{color:var(--muted)}.result-status{display:flex;align-items:center;gap:8px;font-weight:550;margin:4px 0 8px}.status-dot{width:8px;height:8px;background:var(--accent);border-radius:50%;display:inline-block;flex:none}.processing .status-dot{animation:pulse 1.3s infinite}@keyframes pulse{50%{opacity:.25}}.result details{margin-top:12px;color:var(--muted);font-size:11px;overflow-wrap:anywhere}.result details summary{cursor:pointer}.result details dl{display:grid;grid-template-columns:auto 1fr;gap:4px 12px}.result details dd{margin:0;font-family:monospace}.result details dt{font-weight:550}.composer{padding:10px 20px 12px;flex:none;background:var(--bg);border-top:1px solid var(--border)}#send-form{border:1px solid var(--border);border-radius:22px;background:var(--bg);box-shadow:var(--shadow);padding:10px}#message{display:block;border:0;width:100%;padding:8px 10px;max-height:140px;min-height:56px;outline-offset:0;background:transparent}.compose-tools{display:flex;align-items:center;gap:7px}.compose-tools select{border:0;background:var(--panel);border-radius:16px;padding:7px;flex:1;max-width:200px;font-size:12px}.compose-tools .primary{margin-left:auto;font-size:12px;border-radius:18px;white-space:nowrap}.compose-tools .primary span{font-size:17px;margin-left:4px}.composer-note{display:flex;justify-content:flex-end;align-items:baseline;gap:8px;color:var(--muted);font-size:11px;margin:7px 3px 0}.fine{color:var(--muted);font-size:12px;line-height:1.55}#task-help{margin:7px 3px 0}.error{color:var(--danger);font-size:13px;margin:8px 0;overflow-wrap:anywhere}#sources:empty{display:none}#sources{display:flex;align-items:center;gap:8px;overflow:auto;padding:0 0 10px}.source-chip{display:flex;align-items:center;gap:8px;border:1px solid var(--border);border-radius:12px;padding:5px 8px;font-size:11px;min-width:0}.source-chip img{width:35px;height:35px;object-fit:contain;border-radius:5px}.source-chip span{max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.source-chip button{font-size:18px;line-height:1;padding:3px}.connection-message{max-width:500px;margin:60px auto;padding:24px;text-align:center}.connection-message p{margin:12px 0 20px;color:var(--muted)}dialog{color:var(--ink);background:var(--bg);border:1px solid var(--border);box-shadow:var(--shadow);padding:0;max-width:100%;max-height:100dvh}dialog::backdrop{background:#11182755}.history-drawer{position:fixed;inset:0 0 0 auto;margin:0;width:min(430px,100%);height:100dvh;max-height:100dvh;border-radius:0;overflow:hidden}.history-drawer[open]{display:flex;flex-direction:column}.drawer-header{display:flex;justify-content:space-between;align-items:center;padding:20px;gap:16px}.tabs{display:flex;border-bottom:1px solid var(--border)}.tabs button{flex:1;border-radius:0;font-size:14px;padding:12px 8px;position:relative}.tabs button[aria-selected=true]{color:var(--accent)}.tabs button[aria-selected=true]:after{content:"";height:3px;background:var(--accent);border-radius:3px;position:absolute;bottom:0;left:20%;right:20%}.drawer-copy{padding:14px 20px}.drawer-body{overflow:auto;flex:1;min-height:0;padding:0 12px 20px}.date-heading{font-size:12px;color:var(--muted);font-weight:650;margin:16px 8px 8px}.thread-row{border-radius:10px;display:flex;align-items:center;gap:2px;padding:5px 0}.thread-row:hover{background:var(--panel)}.thread-open{flex:1;text-align:left;overflow:hidden;font-weight:500;padding:8px;min-width:0}.thread-open strong{font-weight:550;display:block;overflow-wrap:anywhere}.thread-open small{font-size:10px;color:var(--muted);display:block;margin-top:4px}.thread-actions{display:flex;gap:1px}.thread-actions button{font-size:16px;min-width:28px;padding:6px}.image-library{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:14px 8px}.image-library button{border:1px solid var(--border);padding:7px;text-align:left;overflow:hidden}.image-library img{width:100%;height:120px;object-fit:contain;border-radius:6px}.image-library span{font-size:11px;display:block;overflow-wrap:anywhere}.empty-list{padding:30px 8px;text-align:center;color:var(--muted)}#history-more{margin:8px 20px 16px}.picker{width:min(780px,calc(100% - 28px));border-radius:18px;margin:auto;padding:0 20px 20px;max-height:calc(100dvh - 28px)}.picker .drawer-header{padding:20px 0 12px}.picker>p{margin-bottom:16px}.search-form{margin:16px 0}.search-form label{display:block;margin-bottom:6px;font-weight:550}.search-form>div{display:flex;gap:8px}.search-form input{flex:1}.products{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:12px}.product-card{padding:12px;border:1px solid var(--border);border-radius:12px}.product-card h3{font-size:14px;margin:0}.product-card p{font-size:12px;color:var(--muted);margin:3px 0 10px;overflow-wrap:anywhere}.product-images{display:flex;gap:8px;flex-wrap:wrap}.image-choice{padding:6px;border:1px solid var(--border);width:100%;position:relative}.image-choice img{display:block;width:100%;height:120px;object-fit:contain}.image-choice span{font-size:11px}.image-choice[aria-pressed=true]{border:2px solid var(--accent);background:var(--soft)}.image-choice[aria-pressed=true]:after{content:'✓';position:absolute;top:5px;right:5px;background:var(--accent);color:var(--bg);border-radius:50%;width:22px;height:22px}.picker-footer{display:flex;position:sticky;bottom:-20px;background:var(--bg);justify-content:space-between;align-items:center;border-top:1px solid var(--border);padding:16px 0 0;margin-top:20px;gap:8px}#selected-count{font-size:12px;color:var(--muted)}.small-dialog{width:min(390px,calc(100% - 24px));border-radius:16px;padding:22px;margin:auto}.small-dialog p{margin:14px 0;color:var(--muted)}.small-dialog input{width:100%;margin:7px 0}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}#current-product{font-size:12px}.result .error{padding:6px}.result-label{overflow-wrap:anywhere}
@media(max-width:520px){.topbar{padding:11px 12px}.brand{font-size:16px}.brand-ai{display:none}#conversation{padding:20px 14px 12px}.welcome h1{font-size:23px}.welcome{min-height:210px}.composer{padding:10px 10px 12px}.compose-tools{gap:4px}.compose-tools select{max-width:135px}.compose-tools .primary{font-size:11px;padding:8px}.result{padding:10px}.result-image{max-height:320px}.composer-note{font-size:10px}.picker{width:calc(100% - 12px);max-height:calc(100dvh - 12px);padding:0 14px 14px}.products{grid-template-columns:repeat(2,minmax(0,1fr))}.product-card{padding:8px}.history-drawer .drawer-header{padding:16px}.thread-actions button{min-width:26px;padding:5px}.result-actions{gap:6px}.result-actions button,.result-actions a{padding:6px 9px;font-size:12px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation:none!important}}

/* Compact docked mode follows UnoPim's built-in chat. The expanded workspace
   retains the roomier DreamLayer conversation layout. */
:root.docked{--accent:#7c3aed;--bg:#fff;--panel:#f9fafb;--border:#e5e7eb}
:root.docked.dark{--accent:#b397ff;--bg:#1f1b2d;--panel:#241f35;--border:#453c5f}
.docked .topbar{padding:10px 16px;min-height:52px;border:0;background:linear-gradient(135deg,#6d28d9,#7c3aed 50%,#8b5cf6);color:#fff}
.docked .brand{font-size:13px;font-weight:600;letter-spacing:0;gap:8px;color:#fff}
.docked .brand-mark{width:28px;height:22px;object-fit:contain;flex:none}
.docked .brand-ai{display:none}
.docked .topbar nav{gap:4px}
.docked .topbar button{color:#ffffffd9;min-width:26px;min-height:26px;border-radius:6px;padding:5px;font-size:18px}
.docked .topbar .quiet{font-size:11px}
.docked .topbar button:hover,.docked .topbar button:focus-visible{background:#ffffff26}
.docked .topbar button:focus-visible{outline-color:#fff}
.docked #conversation{padding:20px 16px 16px}
.docked .welcome{min-height:0;padding:24px 0;gap:12px}
.docked .welcome h1{font-size:20px;line-height:1.3;letter-spacing:-.3px}
.docked .welcome p{font-size:13px;line-height:1.55}
.docked .suggestions{gap:6px}
.docked .suggestions button{font-size:12px;padding:7px 10px;border-radius:8px}
.docked .composer{padding:12px}
.docked #send-form{border:1.5px solid #d1d5db;border-radius:12px;padding:0;background:var(--panel);box-shadow:none;overflow:hidden}
.docked.dark #send-form{border-color:#5b4a80}
.docked #send-form:focus-within{border-color:var(--accent)}
.docked #message{font-size:13px;line-height:1.55;padding:12px 14px 6px;min-height:76px;max-height:160px;border-radius:0}
.docked .compose-tools{padding:6px 8px;border-top:1px solid var(--border);gap:4px}
.docked .compose-tools .attach{font-size:20px;min-width:28px;min-height:28px;padding:4px}
.docked .compose-tools select{font-size:11px;border:1px solid var(--border);background:var(--bg);border-radius:6px;padding:4px 6px;max-width:140px}
.docked .compose-tools .primary{font-size:11px;border-radius:8px;padding:7px 9px;background:linear-gradient(135deg,#7c3aed,#8b5cf6);color:#fff;border:0}
.docked .fine,.docked .composer-note{font-size:10px}
.docked .user-message{font-size:13px;border-radius:14px 14px 4px 14px}
.docked .result{border-radius:12px}

/* Conversation tools follow the host chat's compact controls. */
#message:focus-visible{outline:none}#send-form:focus-within{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}
.composer-note{justify-content:space-between}.message-actions{display:flex;gap:14px;align-self:flex-end;padding:0 4px}.result .message-actions{margin:12px 0}.message-actions [aria-pressed=true]{font-weight:700;text-decoration:underline}.task-list{display:flex;flex-direction:column;gap:8px}.task-list button{text-align:start}.small-dialog .drawer-header{padding:0 0 12px}.jump-latest{position:sticky;bottom:0;left:50%;transform:translateX(-50%);box-shadow:var(--shadow);font-size:12px}.image-dialog{width:95vw;height:95dvh;border-radius:12px;padding:12px}.image-dialog .icon-button{position:absolute;right:12px;top:12px;background:var(--bg)}.image-dialog img{width:100%;height:100%;object-fit:contain}.result-image[role=button]{cursor:zoom-in}.dragging{outline:2px dashed var(--accent)}.elapsed{margin-top:8px}.source-chip{flex-shrink:0}#sources{flex-wrap:wrap;max-height:120px}.docked .compose-tools select{max-width:115px}.docked .compose-tools .primary{font-size:10px;padding:7px}.compose-tools .attach{flex-shrink:0}

#connection.reviewing{border-bottom:1px solid var(--border)}#connection.reviewing .connection-message{max-width:800px;margin:0 auto;padding:12px 20px;display:flex;align-items:center;gap:12px;text-align:start}#connection.reviewing h2{font-size:14px}#connection.reviewing p{display:none}#connection.reviewing button{margin-inline-start:auto;font-size:12px;flex-shrink:0}

/* A native textarea preserves keyboard, IME and accessibility behavior. The
   matching text layer colors bound references without changing character widths. */
.message-editor{position:relative}#message-highlight,#message{font:inherit;line-height:1.55;letter-spacing:normal;tab-size:8;white-space:pre-wrap;overflow-wrap:break-word;word-break:normal;padding:8px 10px;border:0;margin:0}#message-highlight{position:absolute;inset:0;overflow:hidden;pointer-events:none;color:var(--ink)}#message{position:relative;color:transparent;caret-color:var(--ink);background:transparent;max-height:160px}#message::placeholder{color:var(--muted);opacity:1}.image-reference{color:var(--accent)}.missing-reference{color:var(--danger);text-decoration:underline wavy}.docked #message-highlight,.docked #message{font-size:13px;line-height:1.55;padding:12px 14px 6px}.source-chip .source-reference{font-size:11px;font-weight:500;line-height:1.4;color:var(--accent);padding:0;max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mention-options{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}.mention-options:empty{display:none}.mention-options button{font-size:12px}.user-message .image-reference{font-weight:inherit}
